(1295596, 166906, 30861, '<td valign="top">Love the object, don''t care for the background. Feelliek it could have been a little more luminous. Nonetheless, a strong entry and a strong score from me.</td>', 'Love the object, don''t care for the background. Feelliek it could have been a little more luminous. Nonetheless, a strong entry and a strong score from me.', '2005-04-16 04:30:06.000000', NULL, 1),
