(1295716, 166987, 33560, '<td valign="top">Remiinds me of the Letterman segment ''Will it Float?''  Great composition, lighting exposure.  Nice, simple idea.</td>', 'Remiinds me of the Letterman segment ''Will it Float?''  Great composition, lighting exposure.  Nice, simple idea.', '2005-04-16 07:00:20.000000', NULL, 1),
(1295717, 166738, 32749, '<td valign="top">Used a bit to much background blur for me, I see what you are doing but just a little much IMHO.</td>', 'Used a bit to much background blur for me, I see what you are doing but just a little much IMHO.', '2005-04-16 07:01:42.000000', NULL, 1),
