(1295794, 167022, 33560, '<td valign="top">I get your point.</td>', 'I get your point.', '2005-04-16 08:09:44.000000', NULL, 1),
(1295795, 167057, 3306, '<td valign="top">This is quite an original and creative entry. I like the tacks of different sizes. They add interest to an already fascinating shot. One of the best of the challenge in my opinion. Great job.</td>', 'This is quite an original and creative entry. I like the tacks of different sizes. They add interest to an already fascinating shot. One of the best of the challenge in my opinion. Great job.', '2005-04-16 08:10:25.000000', NULL, 1),
