(1296817, 166848, 15810, '<td valign="top">great title and interesting take on the challenge. Good lighting andcomposition.</td>', 'great title and interesting take on the challenge. Good lighting andcomposition.', '2005-04-16 19:46:57.000000', NULL, 1),
(1296821, 166964, 15810, '<td valign="top">Brilliant stuff. I''m guessing this is by Arnit. (if I''m wrong take it as a compliment) The composition makes this a ribbon pick for me but the lighting and theme are excellent too. One of my few 10''s. Brilliant.</td>', 'Brilliant stuff. I''m guessing this is by Arnit. (if I''m wrong take it as a compliment) The composition makes this a ribbon pick for me but the lighting and theme are excellent too. One of my few 10''s. Brilliant.', '2005-04-16 19:50:06.000000', NULL, 1),
