(1297617, 167019, 15810, '<td valign="top">Beautiful B&amp;W study. A top finisher.</td>', 'Beautiful B&W study. A top finisher.', '2005-04-17 08:53:33.000000', NULL, 1),
(1297620, 166906, 15810, '<td valign="top">Superb shot, really interesting and obviously time consuming. Great use of colour.</td>', 'Superb shot, really interesting and obviously time consuming. Great use of colour.', '2005-04-17 08:54:52.000000', NULL, 1),
