(1297647, 166966, 32767, '<td valign="top">Strawberry #1 should be in focus. Still a nice idea and photo.</td>', 'Strawberry #1 should be in focus. Still a nice idea and photo.', '2005-04-17 09:49:18.000000', NULL, 1),
(1297648, 167038, 32767, '<td valign="top">Beautiful coloring. Nice Bokeh.</td>', 'Beautiful coloring. Nice Bokeh.', '2005-04-17 09:50:23.000000', NULL, 1),
