(1297650, 166968, 32767, '<td valign="top">Nice photo. Has great stock qualities.</td>', 'Nice photo. Has great stock qualities.', '2005-04-17 09:52:17.000000', NULL, 1),
(1297651, 167053, 32767, '<td valign="top">Great effect. This might be the winner. Good Luck.</td>', 'Great effect. This might be the winner. Good Luck.', '2005-04-17 09:53:42.000000', NULL, 1),
(1297652, 167023, 32767, '<td valign="top">Cool image. Will place high I''m certain. Good Luck.</td>', 'Cool image. Will place high I''m certain. Good Luck.', '2005-04-17 09:54:42.000000', NULL, 1),
(1297655, 167021, 32767, '<td valign="top">The model looks like she wishes to be anywhere else but in front of that lens (no offense to the model). The lightinging has no warmth and is a little to bright. The tacks, which should be the main subject are overpowered by the "you know what" and are out of focus.</td>', 'The model looks like she wishes to be anywhere else but in front of that lens (no offense to the model). The lightinging has no warmth and is a little to bright. The tacks, which should be the main subject are overpowered by the "you know what" and are out of focus.', '2005-04-17 09:59:13.000000', NULL, 1),
(1297658, 166954, 32767, '<td valign="top">I''ve been sailing for years and would loved to have taken this angle on the challenge. Kinda out of the box for those who don''t sail. I hope you''re not getting nailed(pardon the pun) because people expected physical, metal tacks. Nice image (9)</td>', 'I''ve been sailing for years and would loved to have taken this angle on the challenge. Kinda out of the box for those who don''t sail. I hope you''re not getting nailed(pardon the pun) because people expected physical, metal tacks. Nice image (9)', '2005-04-17 10:02:47.000000', NULL, 1),
(1297666, 167057, 35720, '<td valign="top">Great idea and an excellent outcome. Well done! 10</td>', 'Great idea and an excellent outcome. Well done! 10', '2005-04-17 10:11:14.000000', NULL, 1),
(1297667, 166797, 35720, '<td valign="top">Cool shot, I like it a lot. One of the best in this challenge IMO. 10</td>', 'Cool shot, I like it a lot. One of the best in this challenge IMO. 10', '2005-04-17 10:12:01.000000', NULL, 1),
(1297668, 167057, 32997, '<td valign="top">Fun shot..love the light bouncing of the green tack..it works really well...nice light direction.</td>', 'Fun shot..love the light bouncing of the green tack..it works really well...nice light direction.', '2005-04-17 10:12:25.000000', NULL, 1),
(1297672, 167004, 32997, '<td valign="top">Dof works really well here-great idea...would have liked a natural background to increase the need for shelter, and lose the studio feel. Nice shot.</td>', 'Dof works really well here-great idea...would have liked a natural background to increase the need for shelter, and lose the studio feel. Nice shot.', '2005-04-17 10:14:55.000000', NULL, 1),
(1297675, 166953, 32997, '<td valign="top">Surface interesting, composition effective..a bit dark, maybe a little bump of saturation?</td>', 'Surface interesting, composition effective..a bit dark, maybe a little bump of saturation?', '2005-04-17 10:17:53.000000', NULL, 1),
(1297679, 166987, 32997, '<td valign="top">Amazing that you created something this beautiful with this theme..reminds me of the Tao shot in the lines challenge..great work.</td>', 'Amazing that you created something this beautiful with this theme..reminds me of the Tao shot in the lines challenge..great work.', '2005-04-17 10:25:31.000000', NULL, 1),
(1297698, 166763, 29799, '<td valign="top">I dont get the title</td>', 'I dont get the title', '2005-04-17 10:42:13.000000', NULL, 1),
(1297712, 166737, 32997, '<td valign="top">Beautiful shot. Simple yet very effective! In a gimicky theme you have created a solid shot, theme aside. Definitely one of my favourites in this challenge.</td>', 'Beautiful shot. Simple yet very effective! In a gimicky theme you have created a solid shot, theme aside. Definitely one of my favourites in this challenge.', '2005-04-17 10:53:26.000000', NULL, 1),
(1297717, 166983, 32997, '<td valign="top">I like the feel of this shot-good DOF, and nice crop.</td>', 'I like the feel of this shot-good DOF, and nice crop.', '2005-04-17 10:55:44.000000', NULL, 1),
(1297740, 166911, 32997, '<td valign="top">The contrast between gold and black background works here....nice set-up, good shot.</td>', 'The contrast between gold and black background works here....nice set-up, good shot.', '2005-04-17 11:17:19.000000', NULL, 1),
(1297745, 166810, 32997, '<td valign="top">Nice idea..personal preference would have been to place this in a natural setting..on a street corner etc. to give the shot some context. Focus sharp, more depth would be nice.</td>', 'Nice idea..personal preference would have been to place this in a natural setting..on a street corner etc. to give the shot some context. Focus sharp, more depth would be nice.', '2005-04-17 11:20:35.000000', NULL, 1),
(1297752, 166824, 32997, '<td valign="top">Tones effective...composition interesting...I like this shot, well done.</td>', 'Tones effective...composition interesting...I like this shot, well done.', '2005-04-17 11:25:05.000000', NULL, 1),
(1297798, 167064, 19005, '<td valign="top">Looks just like my computer . . . FireFox with a million tabs open!</td>', 'Looks just like my computer . . . FireFox with a million tabs open!', '2005-04-17 12:18:03.000000', NULL, 1),
(1297819, 167027, 6668, '<td valign="top">very creative</td>', 'very creative', '2005-04-17 12:57:56.000000', NULL, 1),
(1297875, 166965, 34134, '<td valign="top">I can''t vote on this challenge, but if I could it would be a HIGH number. Love the colors, the sharpness, the ultra macro and the overall composition.</td>', 'I can''t vote on this challenge, but if I could it would be a HIGH number. Love the colors, the sharpness, the ultra macro and the overall composition.', '2005-04-17 13:59:44.000000', NULL, 1),
(1297883, 167047, 31133, '<td valign="top">This is such a cool idea. I''d love to see a little more sharpness on the four tacks on the table and the "point" of the big tack. Good title, too :-)  The red is so nice here; the collection of tacks looks like a bunch of cranberries. Nice work.</td>', 'This is such a cool idea. I''d love to see a little more sharpness on the four tacks on the table and the "point" of the big tack. Good title, too :-)  The red is so nice here; the collection of tacks looks like a bunch of cranberries. Nice work.', '2005-04-17 14:06:45.000000', NULL, 1),
(1297887, 167019, 31133, '<td valign="top">Haha. Exquisite b&amp;w;  sharp, contrasty, and not a spec of grain.</td>', 'Haha. Exquisite b&w;  sharp, contrasty, and not a spec of grain.', '2005-04-17 14:08:18.000000', NULL, 1),
(1297893, 166986, 31133, '<td valign="top">The composition is nice. I''d love to see the blacks more black to really draw out the contrasts (on my monitor it looks a little light). The shadows on the white background are really good.</td>', 'The composition is nice. I''d love to see the blacks more black to really draw out the contrasts (on my monitor it looks a little light). The shadows on the white background are really good.', '2005-04-17 14:11:55.000000', NULL, 1),
(1297894, 166882, 31133, '<td valign="top">Very sharp and well-composed. Might be nice with a somewhat less strong blue, too.</td>', 'Very sharp and well-composed. Might be nice with a somewhat less strong blue, too.', '2005-04-17 14:13:23.000000', NULL, 1),
(1297895, 167004, 31133, '<td valign="top">Haha, I get the puns! Nice colors. A little more depth of focus to see the tacks in the background would''ve been nice, too.</td>', 'Haha, I get the puns! Nice colors. A little more depth of focus to see the tacks in the background would''ve been nice, too.', '2005-04-17 14:14:35.000000', NULL, 1),
(1297897, 166752, 31133, '<td valign="top">Would be nice to see how this looks with the bunch of tacks away from the center. The blue makes a nice empty space. The tacks look a little oversharpened or something. Very nice colors.</td>', 'Would be nice to see how this looks with the bunch of tacks away from the center. The blue makes a nice empty space. The tacks look a little oversharpened or something. Very nice colors.', '2005-04-17 14:16:19.000000', NULL, 1),
(1297901, 167027, 31133, '<td valign="top">Cute. Must''ve taken some time to make this one! I think it would look really cool agains a white background and maybe with a little unsharp mask, but overall I think you''ve done a good job here.</td>', 'Cute. Must''ve taken some time to make this one! I think it would look really cool agains a white background and maybe with a little unsharp mask, but overall I think you''ve done a good job here.', '2005-04-17 14:17:44.000000', NULL, 1),
(1297903, 166865, 31133, '<td valign="top">Hmmm, this is an interesting little pun. After the challenge, I hope you write what that blue stuff is - or do I really want to know? :-)  The cucumber looks yummy, by the way.</td>', 'Hmmm, this is an interesting little pun. After the challenge, I hope you write what that blue stuff is - or do I really want to know? :-)  The cucumber looks yummy, by the way.', '2005-04-17 14:20:03.000000', NULL, 1),
(1297905, 166795, 31133, '<td valign="top">WOW. This is too clever for words. Beautiful light and composition. One of my favorites so far.</td>', 'WOW. This is too clever for words. Beautiful light and composition. One of my favorites so far.', '2005-04-17 14:21:27.000000', NULL, 1),
(1297908, 166952, 31133, '<td valign="top">What a cute smilie tack. The funny little guy holding the nail (?) could be in better focus, though. It seems like there''s not a strong subject to this shot, but please keep entering challenges!</td>', 'What a cute smilie tack. The funny little guy holding the nail (?) could be in better focus, though. It seems like there''s not a strong subject to this shot, but please keep entering challenges!', '2005-04-17 14:24:30.000000', NULL, 1),
(1297909, 166797, 31133, '<td valign="top">Nice light, composition, and frame.</td>', 'Nice light, composition, and frame.', '2005-04-17 14:26:32.000000', NULL, 1),
(1297910, 166958, 31133, '<td valign="top">Nice. Wonder how it would look with more blue empty space on the right-hand side. This must''ve been some work to compose!</td>', 'Nice. Wonder how it would look with more blue empty space on the right-hand side. This must''ve been some work to compose!', '2005-04-17 14:27:49.000000', NULL, 1),
(1297911, 166932, 31133, '<td valign="top">I love that this is just one single tack! Nice composition, too. (so many of my comments today seem to be related to composition - I guess it''s something I''m trying to pay attention to)</td>', 'I love that this is just one single tack! Nice composition, too. (so many of my comments today seem to be related to composition - I guess it''s something I''m trying to pay attention to)', '2005-04-17 14:28:58.000000', NULL, 1),
(1297912, 167062, 31133, '<td valign="top">Good job! I don''t have anything critical to say - love everything about this one.</td>', 'Good job! I don''t have anything critical to say - love everything about this one.', '2005-04-17 14:29:47.000000', NULL, 1),
(1297913, 166681, 31133, '<td valign="top">I like the idea a lot, but unfortunately, this image doesn''t do alot for me, mainly because of the blurry red tacks framing it. I think if they were gone, this image would be greatly improved.</td>', 'I like the idea a lot, but unfortunately, this image doesn''t do alot for me, mainly because of the blurry red tacks framing it. I think if they were gone, this image would be greatly improved.', '2005-04-17 14:31:51.000000', NULL, 1),
(1297917, 167038, 31133, '<td valign="top">I like the background colors a lot. I wish the tacks were more in focus or prominent somehow, though. That background is killer (in a good way), though.</td>', 'I like the background colors a lot. I wish the tacks were more in focus or prominent somehow, though. That background is killer (in a good way), though.', '2005-04-17 14:33:56.000000', NULL, 1),
(1297918, 167059, 31133, '<td valign="top">I like the puns here.</td>', 'I like the puns here.', '2005-04-17 14:34:40.000000', NULL, 1),
(1297919, 166912, 31133, '<td valign="top">Nice, nice, nice. The drop is exquisite. The white stuff under the tack and rock are slightly distracting, but the eye is drawn to that beautiful water drop and the nail of the tack.</td>', 'Nice, nice, nice. The drop is exquisite. The white stuff under the tack and rock are slightly distracting, but the eye is drawn to that beautiful water drop and the nail of the tack.', '2005-04-17 14:36:22.000000', NULL, 1),
(1297921, 167014, 31133, '<td valign="top">This one is making me have a good laugh. I love the salt (?) and all that symbolism :-) The incense burner in the back probably should''ve been moved so as not to be directly behind the little voodoo doll.</td>', 'This one is making me have a good laugh. I love the salt (?) and all that symbolism :-) The incense burner in the back probably should''ve been moved so as not to be directly behind the little voodoo doll.', '2005-04-17 14:38:01.000000', NULL, 1),
(1297923, 166736, 31133, '<td valign="top">Good use of white space and nice colors.</td>', 'Good use of white space and nice colors.', '2005-04-17 14:39:28.000000', NULL, 1),
(1297924, 166987, 31133, '<td valign="top">Pretty! I never thought tacks and water could be so artistically composed.</td>', 'Pretty! I never thought tacks and water could be so artistically composed.', '2005-04-17 14:40:27.000000', NULL, 1),
(1297925, 166763, 31133, '<td valign="top">I am so glad I read this thread and then cheated so I could come to this point (haha) in life and recognize that this is indeed two petals on a rose. Clever shot.</td>', 'I am so glad I read this thread and then cheated so I could come to this point (haha) in life and recognize that this is indeed two petals on a rose. Clever shot.', '2005-04-17 14:42:19.000000', NULL, 1),
(1297927, 167039, 31133, '<td valign="top">This meets the challenge since it includes tacks, but I have to say this is the hardest entry so far for me to figure out. Hope you explain it after the challenge. Anyway, there''s nice bokeh here and good colors. Not crazy about the photo though, I''m sorry. Wish I could give better input.</td>', 'This meets the challenge since it includes tacks, but I have to say this is the hardest entry so far for me to figure out. Hope you explain it after the challenge. Anyway, there''s nice bokeh here and good colors. Not crazy about the photo though, I''m sorry. Wish I could give better input.', '2005-04-17 14:44:30.000000', NULL, 1),
(1297928, 166741, 31133, '<td valign="top">Beautiful colors!</td>', 'Beautiful colors!', '2005-04-17 14:46:45.000000', NULL, 1),
(1297977, 166972, 33947, '<td valign="top">I like your idea very much. I wish your depth of field were deeper...the blurry foreground pins are a bit of a distraction. Otherwise, I like the simplicity of your composition.</td>', 'I like your idea very much. I wish your depth of field were deeper...the blurry foreground pins are a bit of a distraction. Otherwise, I like the simplicity of your composition.', '2005-04-17 15:27:30.000000', NULL, 1),
(1297989, 166765, 33947, '<td valign="top">I love your idea. It might have worked even better if both tacks were the same color since they''re supposed to be sunglasses, and wish you had been able to get them at the same angle. Fun, regardless.</td>', 'I love your idea. It might have worked even better if both tacks were the same color since they''re supposed to be sunglasses, and wish you had been able to get them at the same angle. Fun, regardless.', '2005-04-17 15:36:19.000000', NULL, 1),
(1298001, 166736, 33947, '<td valign="top">I like the simplicity of your idea. It might have been even more effective if you''d picked three tacks - I don''t know why but the odd number seems to work better - and zooming in and cropping tighter might have made a more powerful statement.</td>', 'I like the simplicity of your idea. It might have been even more effective if you''d picked three tacks - I don''t know why but the odd number seems to work better - and zooming in and cropping tighter might have made a more powerful statement.', '2005-04-17 15:41:51.000000', NULL, 1),
(1298012, 167021, 33947, '<td valign="top">The tacks are badly out of focus, and are a distraction because of it.  The fabric draping down seems okay in soft focus...I like the lines and shadows of it. The wrinkles in the background fabric are also a distration, though. Love your title.</td>', 'The tacks are badly out of focus, and are a distraction because of it.  The fabric draping down seems okay in soft focus...I like the lines and shadows of it. The wrinkles in the background fabric are also a distration, though. Love your title.', '2005-04-17 15:47:19.000000', NULL, 1),
(1298019, 167029, 33947, '<td valign="top">Fun idea, but, as a composition it seems dark.</td>', 'Fun idea, but, as a composition it seems dark.', '2005-04-17 15:50:31.000000', NULL, 1),
(1298024, 166691, 33947, '<td valign="top">Interesting idea, and liked how you cropped it, but, it needs to be much sharper.</td>', 'Interesting idea, and liked how you cropped it, but, it needs to be much sharper.', '2005-04-17 15:52:12.000000', NULL, 1),
(1298027, 166796, 33947, '<td valign="top">Interesting idea, but the composition is a little busy, and the lighting could be better.</td>', 'Interesting idea, but the composition is a little busy, and the lighting could be better.', '2005-04-17 15:53:36.000000', NULL, 1);
