(1314516, 166801, 33947, '<td valign="top">It''s a pleasure to see something this sharp.</td>', 'It''s a pleasure to see something this sharp.', '2005-04-22 23:57:15.000000', NULL, 1),
(1314518, 166937, 33947, '<td valign="top">Effective visual. Well lilt.</td>', 'Effective visual. Well lilt.', '2005-04-22 23:58:18.000000', NULL, 1),
