(1314638, 166713, 24976, '<td valign="top">Almost got your first ribbon! Congrats on the top 10, great photo and keep up the good work :-)</td>', 'Almost got your first ribbon! Congrats on the top 10, great photo and keep up the good work :-)', '2005-04-23 01:23:46.000000', NULL, 0),
(1314642, 167057, 12253, '<td valign="top">Congrat''s Mick!  Great idea, very well done!</td>', 'Congrat''s Mick!  Great idea, very well done!', '2005-04-23 01:27:06.000000', NULL, 0),
(1314644, 167023, 12253, '<td valign="top">Hey Lee, a big congrat''s on your first ribbon!  Great work.</td>', 'Hey Lee, a big congrat''s on your first ribbon!  Great work.', '2005-04-23 01:28:41.000000', NULL, 0),
(1314655, 167023, 27431, '<td valign="top">Good job, Lee. I knew this was a winner the first time I saw it. Now keep up the pace!</td>', 'Good job, Lee. I knew this was a winner the first time I saw it. Now keep up the pace!', '2005-04-23 01:35:02.000000', NULL, 0),
(1314663, 166906, 34192, '<td valign="top">Wow.  I can''t believe all the negative comments about the background.  Maybe I''m weird but I thought that made the image.  Imagine it on plain white like so many other images here at DPC.  You would have ended up last or close to it.  Excellent job and excellent choices!</td>', 'Wow.  I can''t believe all the negative comments about the background.  Maybe I''m weird but I thought that made the image.  Imagine it on plain white like so many other images here at DPC.  You would have ended up last or close to it.  Excellent job and excellent choices!', '2005-04-23 01:41:55.000000', NULL, 0),
(1314685, 166954, 35078, '<td valign="top">Thanks to all those that gave me the good scores and nice comments. I''m happy with my placing, but a little disappointed in the people who obviously marked me down because they didn''t understand that there is more then one meaning for "tacks".</td>', 'Thanks to all those that gave me the good scores and nice comments. I''m happy with my placing, but a little disappointed in the people who obviously marked me down because they didn''t understand that there is more then one meaning for "tacks".', '2005-04-23 02:01:05.000000', NULL, 0),
(1314691, 167023, 21714, '<td valign="top">Congratulations. Very nice work.</td>', 'Congratulations. Very nice work.', '2005-04-23 02:12:03.000000', NULL, 0),
(1314692, 166964, 21714, '<td valign="top">Congratulations. Super job.</td>', 'Congratulations. Super job.', '2005-04-23 02:13:10.000000', NULL, 0),
(1314693, 167057, 21714, '<td valign="top">Congratulations.</td>', 'Congratulations.', '2005-04-23 02:13:41.000000', NULL, 0),
(1314694, 167022, 21714, '<td valign="top">Congratulations. Yep, clever is the word.</td>', 'Congratulations. Yep, clever is the word.', '2005-04-23 02:15:49.000000', NULL, 0),
